// Fontes bitmap proporcionais (ASCII 0x20-0x7E), geradas por
// tools/font2header.py a partir da Open Sans (Apache 2.0, ver
// tools/fonts/LICENSE.txt). Nao editar a mao - rode o script de novo.

struct FontGlyph {
  uint8_t width;
  const uint8_t *bitmap;
};

struct Font {
  uint8_t height;
  uint8_t bytesPerCol;
  const FontGlyph *glyphs;
};

#define FONT_FIRST_CHAR 0x20
#define FONT_LAST_CHAR 0xFF
#define FONT_GLYPH_COUNT (FONT_LAST_CHAR - FONT_FIRST_CHAR + 1)

